def main(num_ms: int, num_matched: int, upper_limit: int, diagram_credit: int) -> dict:
    point = 0
    if num_matched <= 0:
        return {"result": point}

    point = (num_matched/num_ms)* upper_limit + diagram_credit
    point = min(point, upper_limit)
    return {
        "result": point
    }

def main(num_ms: int, num_matched: int, upper_limit) -> dict:
    point = 0
    if num_matched <= 0:
        return {"result": point}

    point = float(num_matched)/float(num_ms)*upper_limit
    return {
        "result": int(point)
    }

